// Defensive password lifecycle: hash, verify, upgrade, revoke.
const argon2 = require("argon2")

// 1) Registration: unique salt is generated inside the hash string.
async function register(email, password) {
  const hash = await argon2.hash(password, {
    type: argon2.argon2id,
    memoryCost: 19456, // 19 MiB
    timeCost: 2,
    parallelism: 1
  })
  await db.users.insert({ email, passwordHash: hash, tokenVersion: 1 })
}

// 2) Login: verify against the stored hash; parameters travel with it.
async function login(email, password) {
  const user = await db.users.byEmail(email)
  if (!user) return null
  const ok = await argon2.verify(user.passwordHash, password)
  if (!ok) return null
  if (argon2.needsRehash(user.passwordHash)) {
    // Transparent upgrade to current cost parameters.
    await db.users.setHash(user.id, await argon2.hash(password, {
      type: argon2.argon2id, memoryCost: 19456, timeCost: 2
    }))
  }
  return user
}

// 3) Password change: bump tokenVersion -> all old sessions die.
async function changePassword(userId, newPassword) {
  const hash = await argon2.hash(newPassword, { type: argon2.argon2id })
  await db.users.updatePassword(userId, hash)
  await db.users.bumpTokenVersion(userId) // revocation in one write
}
